window.portfolioCollection=[{"id":"rory","title":"Confess your marketing sins to AI Rory","category":"Live experiences","video":"pl3mb34ZxRg","images":[{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5cbb7831c8a1455c631e72_6a5cb9ed9a60ab3cb307ed51_rory-real-making-of-montage.jpeg","alt":"Real MADFest exhibition installation beside Rory Sutherland with Yepic founder Aaron Jones during production"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5cbd5d35b21e1d59a64b62_6a5bb101ac944938d39f3cce_rory-madfest-bless-me-rory-artwork.png","alt":"Bless Me Rory For I Have Branded campaign flyer for the MADFest AI experience"}],"note":"","role":"Creative technologist · Creative and technical delivery · With Yepic","body":[["The idea","Rory wanted a confessional where marketers could confess their marketing sins. The person listening would be a digital version of him: his voice, his personality, even his vape."],["What I did","I secured Rory’s involvement and brought the creative and technical work together. We filmed him, developed the avatar experience, and designed, built and delivered the physical confessional in five days."],["The experience","Hundreds of people spoke to digital Rory over the event. For me, the challenge was capturing what makes Rory Rory, then making that work as a live conversation—not just a video on a screen."]]},{"id":"live-hosts","title":"A conversation with the whole conference","category":"Live experiences","video":"v1hy3UyTWuM","images":[{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5ba1a2ca1b5a91cd7bea72_6a5ba0e78374d7fa56973cd5_ltw-live-personas-1.jpeg","alt":"Yepic team with the Oli Barrett and Susannah Streeter AI personas at London Tech Week"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5bb7af20d3df490bcf86fb_6a5bb6049f24612fc9c86a56_ltw-susannah-green-screen-01.jpeg","alt":"Susannah Streeter being filmed on green screen for her London Tech Week AI persona"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5bb7af20d3df490bcf8701_6a5bb60543a0b1ee56d1f203_ltw-susannah-yepic-team-02.jpeg","alt":"Susannah Streeter with the Yepic production team after filming"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5bb7af20d3df490bcf86fe_6a5bb6059f24612fc9c86ab9_ltw-susannah-post-production-03.jpeg","alt":"Post-production timeline for Susannah Streeter's AI persona"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5bb7af20d3df490bcf8706_6a5bb60520d3df490bcf0e38_ltw-oli-portrait-05.jpeg","alt":"Oli Barrett seated during the AI persona filming session"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5ba1a2ca1b5a91cd7bea76_6a5ba0e7cf8fc1f2f6f9585b_ltw-live-personas-2.jpeg","alt":"An attendee speaking with Susannah Streeter's AI persona at London Tech Week"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5ba1a3ca1b5a91cd7bea7e_6a5ba0e8c93bd8eaa16201a3_ltw-live-personas-4.jpeg","alt":"Oli Barrett beside his live Yepic AI persona at London Tech Week"}],"note":"","role":"Creative technologist · Real-time avatars and live knowledge · With Yepic","body":[["The idea","Oli Barrett and Susannah Streeter were hosting London Tech Week. We made AI versions that visitors could speak with, informed by what was happening across the stages."],["What I did","My work brought together the conversational avatars and live stage transcripts. The aim was to connect what speakers were saying to what visitors wanted to know, while the event was still happening."],["The experience","Visitors could discuss a talk, catch up on something they had missed or explore what to attend next. The interesting part was making the event’s knowledge available through a conversation."]]},{"id":"international","title":"Your first interview, with room to practise","category":"Live experiences","video":"qfdZtaxYOF0","images":[{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5b7afd1c1d33a1d5ab94a3_maxresdefault.jpeg","alt":"Arabic-speaking AI employment coach for SDAIA and King Saud University"}],"note":"Publisher video: “AI Interview Rough Cut”.","role":"Creative technologist · Interactive interview experience · With Yepic","body":[["The idea","Imagine leaving university without ever having had a job interview. For SDAIA and King Saud University, we built an experience where students could practise before that first real opportunity."],["What I did","I worked on the live interactive interview and feedback experience: an avatar that could conduct a practice conversation and help the student understand how they had done."],["The experience","Around a hundred students took part in five-minute practice interviews. This was AI doing something very human: giving someone a place to try, get feedback and feel better prepared."]]},{"id":"oman","title":"AI video for a national election","category":"Live experiences","video":"CJGsZMNTwOo","images":[{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5b7afe1c1d33a1d5ab94b7_maxresdefault.jpeg","alt":"Yepic avatar system supporting Oman’s digital Shura election"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5cbff64cd40be74add4464_6a5cbf0ea633781a09db9a54_oman-election-team-officials.jpeg","alt":"Yepic team with Oman election officials during the digital election programme"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5cbff64cd40be74add4469_6a5cbf0e10d19c0f743a63d8_oman-election-working-session.jpeg","alt":"Yepic working session during the Oman digital election delivery"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5cbff64cd40be74add444f_6a5cbf0f9f8601dd252ad815_oman-election-faces-behind-avatar.jpeg","alt":"The people behind the Oman election avatar project"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5cc34d69ac37d776ea9566_6a5cc2fe314d9b41e8bc3f79_oman-election-delivery-day-fixed.jpeg","alt":"Oman digital election project delivery day"}],"note":"","role":"Creative technologist · Hands-on implementation · With Yepic and Oracle","body":[["The brief","Working with Oracle, we were trusted to deliver AI video for Oman’s Shura Council election campaign."],["What I did","I personally crafted the AI video workflow for this project. My role was hands-on implementation: taking the technology and making it work for the campaign."],["Why it matters","This was not a speculative demo. It was work for a national election campaign, where delivery and the way information reached people mattered."]]},{"id":"research","title":"Making aviation data understandable","category":"Enterprise engineering","video":null,"images":[{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5ccb6b30cc59044eacbbe9_6a5cc7a69a60ab3cb30b5b75_ada-ai-avatar-hangar-concept.jpeg","alt":"Conceptual visualisation of an enterprise AI avatar operating in an Abu Dhabi aviation hangar"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5ccb6c30cc59044eacbbf3_6a5cca45ca2ffe1ab62c17a4_ada-safety-briefing-concept.jpeg","alt":"AI-generated conceptual visualisation of multilingual avatar-led aviation safety guidance"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5ccb6c30cc59044eacbc04_6a5cca7d6e12902c4a9cacfd_ada-secure-integration-concept.jpeg","alt":"AI-generated conceptual visualisation of permission-aware aviation data, charts and graphs"},{"src":"https://cdn.prod.website-files.com/619e8219a59fbac24cdb021a/6a5ccb6c30cc59044eacbbfa_6a5ccac584f1913bbd33def9_ada-cross-device-testing-concept.jpeg","alt":"AI-generated conceptual visualisation of enterprise aviation interface testing across devices"}],"note":"Illustrative images only. The source identifies these as AI-generated concepts, not photographs or screenshots of the deployment.","role":"Technical lead · System design and coding · With Yepic and Oracle","body":[["The problem","Staff were working with older airport systems that needed specialist short codes. Even asking a simple question could require years of experience."],["What I built","I led, delivered and coded an interface that let people ask in ordinary language, with charts and an avatar explaining the answer. Speech recognition, the language model, voice and video had to run on local hardware."],["The hard part","We built for an L40, with different access permissions and a demanding latency target. My job was to make the whole local pipeline responsive, rather than rely on the cloud services we normally used."]]},{"id":"good-omen","title":"Two products. Twenty hours. First place.","category":"Hackathon wins","role":"Good Omen team: Aaron Jones, Giovanni Funchal and Marko Stapfner","body":[["The challenge","At Project Europe × Lovable in Stockholm, our team built a journalist avatar and a real-time video tool in under twenty hours."],["What happened","Good Omen won the competition. Impact Loop acquired the journalist tool, giving the project a life beyond the hackathon."],["Why it matters","This is the kind of work I enjoy: a demanding brief, a small team and a working product people can actually use."]],"links":[["Impact Loop’s account","https://www.impactloop.com/artikel/impact-loop-s-avatar-idea-wins-at-lovable-and-project-europe-hackathon"],["Watch my Video Moonshot demo post","https://www.linkedin.com/posts/aaronbenjaminjones_goodomen-ai-video-activity-7365483054498209794-qXtD"]],"images":[{"src":"assets/good-omen-stockholm.jpg","alt":"Good Omen with Impact Loop in Stockholm. Photograph: Jesper Andersson / Impact Loop."}]},{"id":"ai-engine","title":"Good Omen takes the overall win","category":"Hackathon wins","role":"With Giovanni Funchal and Marko Stapfner","body":[["The project","Our Good Omen team built Summer Chat, a conversational AI project, at the AI Engine Summer Hack."],["The result","The organiser named Summer Chat the overall winner. That collaboration continued into our Stockholm hackathon entry."]],"links":[["Organiser’s results and photographs","https://jamesin.substack.com/p/summer-hack"]],"images":[{"src":"assets/good-omen-summer.jpeg","alt":"Good Omen presenting at the AI Engine Summer Hack. Photograph: Adam Isfendiyar."}]},{"id":"storymachine","title":"More time creating. Less time waiting.","category":"Products","role":"StoryMachine / Product building and real-time creative AI","body":[["What I’m building","I’m building StoryMachine so people can explore creative directions together, with agents helping them research, plan and visualise their ideas."],["Why it matters","Fast generation is only part of the problem. People need a way to develop a story, compare possibilities and decide what is worth making. My work connects those creative decisions to the technology."]],"links":[]},{"id":"open-source","title":"Building, testing and sharing code","category":"Open source","role":"Projects and experiments across multiple repositories","body":[["What I’m working on","I work across multiple repositories, building and testing real-time AI, video generation and creative tools."],["Explore the work","My GitHub brings together my public projects, experiments and research resources."]],"links":[["Explore my GitHub","https://github.com/yepicaiaaron"]]},{"id":"ai-consulting","title":"Helping a team become capable with AI","category":"Consulting","role":"Lead AI engineering consultant / General Purpose","images":[{"src":"assets/saudi-speaking.jpeg","alt":"Aaron speaking on stage. Speaking photograph, not a client training session."}],"body":[["Where we start","I help leaders work out where AI could make a difference, what to do first and how to bring their people with them."],["What I do","Alongside strategy and executive coaching, I teach teams to use tools such as Claude Code, build agents and apply them to their own work. The goal is to leave people capable of taking the next step themselves."]],"links":[]},{"id":"fikay","title":"A business that helped families earn","category":"Earlier ventures","role":"Founder / Fikay Fashion","body":[["The beginning","After volunteering in Cambodia, I wanted to help parents earn a living so their children could stay in education. Fikay made fashion accessories from recycled materials, working with local producers."],["Recognition","I received the British Empire Medal in 2016 for services to ethical fashion, and the University of Essex named me Alumnus of the Year in 2018."]],"links":[["University of Essex profile","https://www.essex.ac.uk/alumni/awards/alumnus-of-the-year/2018"]],"images":[{"src":"assets/aaron-fikay.jpg","alt":"Aaron Jones in the University of Essex Alumnus of the Year profile."}]},{"id":"seefashion","title":"Helping people discover what they love","category":"Earlier ventures","role":"Founder / SeeFashion","body":[["The product","With SeeFashion, I worked on computer vision and machine learning for personalised shopping and product discovery."],["The connection","The question that interested me was how technology could understand what someone was looking for and make the experience more useful to them."]],"links":[["University of Essex profile","https://www.essex.ac.uk/alumni/awards/alumnus-of-the-year/2018"]]},{"id":"creative-community","title":"Give people space. They’ll surprise you.","category":"Creative communities","role":"Big Screen Hack / Bringing filmmakers, engineers and partners together","images":[{"src":"assets/lilies-film.jpg","alt":"lilies — Muja Studios / Jabir Mohammed. Big Screen Hack Cannes, Film Track 1st / Best in Show."},{"src":"assets/bsh-shared-imagination.png","alt":"Conceptual illustration: filmmakers and engineers around a shared workbench, a ribbon of film rising to the Big Screen Hack screen and a cinema audience. AI-generated artwork, not an event photograph."}],"body":[["Why make space for creativity?","An unfamiliar tool can be intimidating on your own. In a room with people who share what they know, you can try an idea, see what happens and try again. That freedom matters: it gives people the confidence to make something they would not have attempted alone."],["What I brought together","I brought filmmakers, engineers and technology partners together, with tools to explore, a shared deadline and a real screening to work towards. Filmmakers brought story and taste. Engineers helped them discover new ways to realise those ideas. My job was to make that collaboration possible."],["Why the cinema matters","A deadline turns experiments into decisions. An audience gives those decisions a purpose. Teams made films in 48 hours, and work was screened at Cinéum Cannes during festival week. Big Screen Hack gives emerging creative work a place to begin, people to develop it with and somewhere to be seen."]],"links":[["About Big Screen Hack","https://www.bigscreenhack.com/"],["Film credits and screening record","https://www.bigscreenhack.com/film/lilies.html"]],"video":"UZgBSVi-kpc","note":"Participant film: lilies, by Muja Studios / Jabir Mohammed. My role was organising the event, not making this film. The Cinéum screening was an independent event during Cannes festival week."},{"id":"video-foundations","title":"Taking zero-shot talking photos to market","category":"Generative video","role":"Founder / Yepic AI","images":[{"src":"assets/optimised/yepic-studio-interface.webp","alt":"Yepic Studio interface, from its Product Hunt gallery"}],"body":[["Seeing it early","I began working on AI video in 2019, exploring what generative models could make possible for communication."],["Building the technology","At Yepic, we developed zero-shot talking photos: a single image could become a talking face without training a separate model for that person. I brought research, engineering and product development together to make this technology available commercially from 2020."],["Beyond the demo","By 2022, OVHcloud’s account documented more than a million videos generated with Yepic Studio, alongside work on simultaneous video translation."]],"links":[["Yepic Studio and the RoyalAIness launch record","https://www.producthunt.com/products/yepic-ai-her-royalainess-invites"],["OVHcloud’s 2022 account","https://www.ovhcloud.com/sites/default/files/casestudy/casestudy-yepic-ovhcloud-en-022022_1_1.pdf"]]},{"id":"world-models","title":"From watching a world to interacting with it","category":"Current research","role":"Real-time video / World models / Research and product development","body":[["What I’m exploring","I’m working on world models and real-time video: experiences that can change in response to what someone does, rather than a clip they simply watch."],["Why now","My work has moved from visual recognition to video generation to live interaction. World models are the next part of that journey."],["What I want to build","Tools that let people explore an idea together, see different possibilities and shape the direction while it is still taking form. This is active research and development, not a finished capability claim."]],"links":[["My real-time video research collection","https://github.com/yepicaiaaron/awesome-realtime-video-generation"]]}];